window.__EPHONE_HTML_PARTS[14] = "<!-- 天气设置 (仅单聊显示) - UI 优化版 -->\n<div class=\"settings-section\" id=\"weather-settings-section\" style=\"display: none;\">\n    <!-- 开关行 -->\n    <div class=\"settings-item\">\n        <label>启用实时天气同步</label>\n        <label class=\"toggle-switch\">\n            <input type=\"checkbox\" id=\"enable-weather-switch\">\n            <span class=\"slider\"></span>\n        </label>\n    </div>\n    \n    <!-- 详情配置区域 (由JS控制显示/隐藏) -->\n    <div id=\"weather-config-container\" style=\"display: none;\">\n        \n        <!-- 我的位置 -->\n        <div class=\"settings-item-block\">\n            <label style=\"font-weight: 500;\">我的位置 (User)</label>\n            <div class=\"weather-input-group\">\n                <input type=\"text\" id=\"user-virtual-city\" placeholder=\"虚拟名 (如: 龙城)\" class=\"weather-input\">\n                <input type=\"text\" id=\"user-real-city-search\" placeholder=\"真实城市 (拼音/英文)\" class=\"weather-input\">\n                <button id=\"user-city-search-btn\" class=\"settings-mini-btn\" style=\"margin-left: 0;\">搜索</button>\n            </div>\n            <!-- 隐藏域 -->\n            <input type=\"hidden\" id=\"user-city-lat\">\n            <input type=\"hidden\" id=\"user-city-lon\">\n            <!-- 结果展示 -->\n            <div id=\"user-city-result\" class=\"weather-result-text\">未设置映射</div>\n        </div>\n\n        <!-- 对方位置 -->\n        <div class=\"settings-item-block\" style=\"border-bottom: none;\">\n            <label style=\"font-weight: 500;\">对方位置 (Char)</label>\n            <div class=\"weather-input-group\">\n                <input type=\"text\" id=\"char-virtual-city\" placeholder=\"虚拟名 (如: 哥谭)\" class=\"weather-input\">\n                <input type=\"text\" id=\"char-real-city-search\" placeholder=\"真实城市 (拼音/英文)\" class=\"weather-input\">\n                <button id=\"char-city-search-btn\" class=\"settings-mini-btn\" style=\"margin-left: 0;\">搜索</button>\n            </div>\n            <!-- 隐藏域 -->\n            <input type=\"hidden\" id=\"char-city-lat\">\n            <input type=\"hidden\" id=\"char-city-lon\">\n            <!-- 结果展示 -->\n            <div id=\"char-city-result\" class=\"weather-result-text\">未设置映射</div>\n        </div>\n\n    </div>\n</div>\n\n        <!-- 视频通话优化设置 -->\n        <div class=\"settings-section\" id=\"video-call-optimization-section\">\n            <!-- 开关行 -->\n            <div class=\"settings-item\">\n                <label>视频通话优化</label>\n                <label class=\"toggle-switch\">\n                    <input type=\"checkbox\" id=\"enable-video-optimization-switch\">\n                    <span class=\"slider\"></span>\n                </label>\n            </div>\n            \n            <!-- 详情配置区域 (由JS控制显示/隐藏) -->\n            <div id=\"video-optimization-config-container\" style=\"display: none;\">\n                \n                <!-- 对方视频图片 -->\n                <div class=\"settings-item-block\">\n                    <label style=\"font-weight: 500;\">对方视频画面</label>\n                    <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 8px;\">\n                        <img id=\"remote-video-preview\" src=\"\" \n                             style=\"width: 80px; height: 80px; border-radius: 8px; object-fit: cover; border: 2px solid #ddd; display: none;\">\n                        <div id=\"remote-video-placeholder\" style=\"width: 80px; height: 80px; border-radius: 8px; background: #f0f0f0; display: flex; align-items: center; justify-content: center; font-size: 12px; color: #999;\">未设置</div>\n                    </div>\n                    <div style=\"display: flex; gap: 8px; margin-top: 10px;\">\n                        <button class=\"settings-mini-btn\" onclick=\"document.getElementById('remote-video-input').click()\">本地上传</button>\n                        <button class=\"settings-mini-btn\" id=\"remote-video-url-btn\">URL上传</button>\n                        <button class=\"settings-mini-btn\" id=\"remote-video-reset-btn\" style=\"background: #ff3b30; color: white;\">重置</button>\n                        <input type=\"file\" id=\"remote-video-input\" accept=\"image/*\" hidden>\n                    </div>\n                    <input type=\"text\" id=\"remote-video-url-input\" placeholder=\"或输入图片URL\" \n                           style=\"width: 100%; padding: 8px; margin-top: 8px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\n                </div>\n\n                <!-- 我方视频图片 -->\n                <div class=\"settings-item-block\" style=\"border-bottom: none;\">\n                    <label style=\"font-weight: 500;\">我方视频画面</label>\n                    <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 8px;\">\n                        <img id=\"local-video-preview\" src=\"\" \n                             style=\"width: 80px; height: 80px; border-radius: 8px; object-fit: cover; border: 2px solid #ddd; display: none;\">\n                        <div id=\"local-video-placeholder\" style=\"width: 80px; height: 80px; border-radius: 8px; background: #f0f0f0; display: flex; align-items: center; justify-content: center; font-size: 12px; color: #999;\">未设置</div>\n                    </div>\n                    <div style=\"display: flex; gap: 8px; margin-top: 10px;\">\n                        <button class=\"settings-mini-btn\" onclick=\"document.getElementById('local-video-input').click()\">本地上传</button>\n                        <button class=\"settings-mini-btn\" id=\"local-video-url-btn\">URL上传</button>\n                        <button class=\"settings-mini-btn\" id=\"local-video-reset-btn\" style=\"background: #ff3b30; color: white;\">重置</button>\n                        <input type=\"file\" id=\"local-video-input\" accept=\"image/*\" hidden>\n                    </div>\n                    <input type=\"text\" id=\"local-video-url-input\" placeholder=\"或输入图片URL\" \n                           style=\"width: 100%; padding: 8px; margin-top: 8px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\n                </div>\n\n                <!-- 真实摄像头设置 -->\n                <div class=\"settings-item-block\" style=\"border-bottom: none; padding-top: 15px; border-top: 1px solid #e0e0e0; margin-top: 15px;\">\n                    <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;\">\n                        <label style=\"font-weight: 500;\">使用真实摄像头</label>\n                        <label class=\"toggle-switch\">\n                            <input type=\"checkbox\" id=\"enable-real-camera-switch\">\n                            <span class=\"slider\"></span>\n                        </label>\n                    </div>\n                    <div style=\"font-size: 12px; color: #666; margin-bottom: 10px;\">\n                        启用后，我方画面将使用设备摄像头，AI可以真正\"看到\"你\n                    </div>\n                    \n                    <!-- 截图间隔设置 -->\n                    <div id=\"camera-interval-setting\" style=\"display: none;\">\n                        <div style=\"display: flex; align-items: center; gap: 10px; margin-top: 10px;\">\n                            <label style=\"font-size: 13px; white-space: nowrap;\">截图间隔</label>\n                            <input type=\"number\" id=\"camera-capture-interval\" \n                                   min=\"1\" max=\"60\" value=\"5\" \n                                   style=\"width: 60px; padding: 6px; border: 1px solid #ddd; border-radius: 6px; font-size: 13px;\">\n                            <span style=\"font-size: 13px; color: #666;\">秒</span>\n                        </div>\n                        <div style=\"font-size: 11px; color: #999; margin-top: 5px;\">\n                            定时截取摄像头画面发送给AI，默认5秒\n                        </div>\n                        \n                        <!-- 使用后置摄像头开关 -->\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-top: 12px;\">\n                            <label style=\"font-size: 13px;\">使用后置摄像头</label>\n                            <label class=\"toggle-switch\">\n                                <input type=\"checkbox\" id=\"enable-rear-camera-switch\">\n                                <span class=\"slider\"></span>\n                            </label>\n                        </div>\n                        <div style=\"font-size: 11px; color: #999; margin-top: 5px;\">\n                            开启后将切换为后置摄像头（仅移动设备有效）\n                        </div>\n\n                        <!-- 摄像头状态 -->\n                        <div id=\"camera-status\" style=\"margin-top: 10px; padding: 8px; background: #f9f9f9; border-radius: 6px; font-size: 12px; display: none;\">\n                            <div style=\"display: flex; align-items: center; gap: 5px;\">\n                                <span id=\"camera-status-icon\" style=\"width: 8px; height: 8px; border-radius: 50%; background: #ccc;\"></span>\n                                <span id=\"camera-status-text\" style=\"color: #666;\">摄像头未激活</span>\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <!-- 仅读取对话开关 -->\n                    <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid #e0e0e0;\">\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                            <label style=\"font-weight: 500; font-size: 13px;\">仅读取对话内容</label>\n                            <label class=\"toggle-switch\" style=\"transform: scale(0.9);\">\n                                <input type=\"checkbox\" id=\"tts-dialogue-only-switch\">\n                                <span class=\"slider\"></span>\n                            </label>\n                        </div>\n                        <div style=\"font-size: 11px; color: #666; line-height: 1.5;\">\n                            启用后，语音播报只读取引号内的对话，不读取动作描写等旁白内容\n                        </div>\n                    </div>\n\n                    <!-- 旁白对话穿插模式 -->\n                    <div style=\"margin-top: 15px; padding-top: 15px; border-top: 1px solid #e0e0e0;\">\n                        <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;\">\n                            <label style=\"font-weight: 500; font-size: 13px;\">旁白与对话穿插</label>\n                            <label class=\"toggle-switch\" style=\"transform: scale(0.9);\">\n                                <input type=\"checkbox\" id=\"video-interleaved-mode-switch\">\n                                <span class=\"slider\"></span>\n                            </label>\n                        </div>\n                        <div style=\"font-size: 11px; color: #666; line-height: 1.5;\">\n                            启用后，旁白和对话按自然顺序穿插显示，而非旁白合并在前、对话在后\n                        </div>\n                    </div>\n                </div>\n\n            </div>\n        </div>\n\n        <!-- 记忆库区域 -->\n        <div class=\"settings-section\" id=\"memory-archive-section\">\n            <div class=\"settings-item\">\n                <label style=\"font-weight: 600; font-size: 16px;\">记忆库</label>\n            </div>\n            \n            <div id=\"memory-archive-container\" style=\"padding: 0 15px;\">\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\n                    保存当前聊天的所有记录和设置（人设、头像、长期记忆、语音、预设等），方便多路线管理\n                </div>\n                \n                <button id=\"save-memory-archive-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\n                    保存当前状态\n                </button>\n                \n                <div id=\"memory-archive-list\" style=\"display: flex; flex-direction: column; gap: 10px;\">\n                    <!-- 存档列表将动态生成 -->\n                </div>\n            </div>\n        </div>\n\n        <!-- API调用历史区域 -->\n        <div class=\"settings-section\" id=\"api-history-section\">\n            <div class=\"settings-item\">\n                <label style=\"font-weight: 600; font-size: 16px;\">API调用历史</label>\n            </div>\n            \n            <div style=\"padding: 0 15px;\">\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\n                    查看每次发送给AI的原始提示词、调用信息和返回的原始数据\n                </div>\n                \n                <button id=\"view-api-history-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\n                    查看返回的提示词\n                </button>\n            </div>\n        </div>\n\n        <!-- 消息导航区域 -->\n        <div class=\"settings-section\" id=\"message-navigation-section\">\n            <div class=\"settings-item\">\n                <label style=\"font-weight: 600; font-size: 16px;\">消息导航</label>\n            </div>\n            \n            <div style=\"padding: 0 15px;\">\n                <div style=\"margin-bottom: 15px; color: var(--text-secondary); font-size: 13px;\">\n                    快速跳转到聊天记录的开头或结尾。当聊天记录较多时，可能会有轻微延迟。\n                </div>\n                \n                <button id=\"scroll-to-first-message-btn\" class=\"form-button\" style=\"margin-bottom: 10px;\">\n                    回到第一条消息\n                </button>\n                \n                <button id=\"scroll-to-last-message-btn\" class=\"form-button\" style=\"margin-bottom: 15px;\">\n                    回到最后一条消息\n                </button>\n            </div>\n        </div>\n\n        <!-- 第四组：高级功能 (TTS, NAI, 线下模式) -->\n        <div class=\"settings-section\">\n             <!-- 时间戳显示格式 -->\n             <div class=\"settings-item\">\n                 <div>\n                     <div style=\"font-weight: 500;\">显示秒数</div>\n                     <div style=\"font-size: 12px; color: var(--text-secondary);\">开启后，此聊天的时间戳将显示为\"时:分:秒\"格式（覆盖全局设置）</div>\n                 </div>\n                 <label class=\"toggle-switch\">\n                     <input type=\"checkbox\" id=\"chat-show-seconds-switch\">\n                     <span class=\"slider\"></span>\n                 </label>\n             </div>\n             \n             <!-- 语音 -->\n             <div class=\"settings-item\" id=\"tts-enable-group\">\n                 <label>启用语音合成 (TTS)</label>\n                 <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"enable-tts-switch\"> <span class=\"slider\"></span> </label>\n             </div>\n              <div class=\"settings-item tts-settings\" id=\"tts-provider-group\">\n                  <label for=\"tts-provider-select\">语音服务</label>\n                  <div class=\"settings-right\"><select id=\"tts-provider-select\" class=\"settings-select\"><option value=\"minimax\">MiniMax</option><option value=\"elevenlabs\">ElevenLabs</option></select></div>\n              </div>\n             <div class=\"settings-item\" id=\"ai-voice-id-group\">\n                 <label>语音 ID</label>\n                 <div class=\"settings-right\">\n                    <input type=\"text\" id=\"ai-voice-id-input\" placeholder=\"minimax voice_id\">\n                 </div>\n             </div>\n              <div class=\"tts-settings\" id=\"elevenlabs-role-options\" hidden>\n                <div class=\"settings-item\"><label for=\"elevenlabs-voice-search\">搜索音色</label><div class=\"settings-right\"><input type=\"text\" id=\"elevenlabs-voice-search\" placeholder=\"输入名称\"></div></div>\n                <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"elevenlabs-voice-fetch\">获取音色</button><button type=\"button\" class=\"form-button\" id=\"elevenlabs-voice-next\" hidden>加载更多</button></div>\n                <div class=\"settings-item\"><label for=\"elevenlabs-voice-select\">可用音色</label><div class=\"settings-right tts-controls\"><select id=\"elevenlabs-voice-select\" class=\"settings-select\"><option value=\"\">选择音色（也可手填 ID）</option></select></div></div>\n                <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"elevenlabs-voice-sample\">播放示例</button><button type=\"button\" class=\"form-button\" id=\"elevenlabs-favorite-add\">收藏音色</button></div>\n                <details><summary>收藏与声音参数</summary>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-favorite-select\">收藏音色</label><div class=\"settings-right\"><select id=\"elevenlabs-favorite-select\" class=\"settings-select\"><option value=\"\">收藏的音色</option></select></div></div>\n                  <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"elevenlabs-favorite-remove\">取消收藏</button></div>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-role-model\">角色模型</label><div class=\"settings-right\"><input type=\"text\" id=\"elevenlabs-role-model\" placeholder=\"留空跟随 API 设置\"></div></div>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-stability\">稳定度</label><div class=\"settings-right\"><input type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" id=\"elevenlabs-stability\" placeholder=\"沿用音色设置\"></div></div>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-similarity_boost\">相似度</label><div class=\"settings-right\"><input type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" id=\"elevenlabs-similarity_boost\" placeholder=\"沿用音色设置\"></div></div>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-style\">风格强度</label><div class=\"settings-right\"><input type=\"number\" min=\"0\" max=\"1\" step=\"0.05\" id=\"elevenlabs-style\" placeholder=\"沿用音色设置\"></div></div>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-speaker-boost\">声音增强</label><div class=\"settings-right\"><select id=\"elevenlabs-speaker-boost\" class=\"settings-select\"><option value=\"\">沿用音色设置</option><option value=\"true\">开启</option><option value=\"false\">关闭</option></select></div></div>\n                  <p class=\"tts-usage\">模型不支持的参数需留空。风格与声音增强可能增加生成时间。</p>\n                  <div class=\"settings-item\"><label for=\"elevenlabs-sound-preset\">参数预设</label><div class=\"settings-right\"><select id=\"elevenlabs-sound-preset\" class=\"settings-select\"><option value=\"\">声音参数预设</option></select></div></div>\n                  <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"elevenlabs-preset-save\">保存参数</button><button type=\"button\" class=\"form-button\" id=\"elevenlabs-preset-apply\">应用参数</button><button type=\"button\" class=\"form-button\" id=\"elevenlabs-preset-delete\">删除预设</button></div>\n                </details>\n                <div class=\"settings-item\"><label>聊天流式播放</label><label class=\"toggle-switch\"><input type=\"checkbox\" id=\"tts-stream-switch\"><span class=\"slider\"></span></label></div><p class=\"tts-usage\">支持时边接收边播放；其他浏览器使用同一次请求的完整音频。分段语音顺序播放。</p><div class=\"settings-item\"><label>长文本分段</label><label class=\"toggle-switch\"><input type=\"checkbox\" id=\"tts-split-long-switch\"><span class=\"slider\"></span></label></div>\n                <p class=\"tts-usage\">超出模型限制时按句分段；多段下载为 ZIP 音频包，不截断正文。</p>\n              </div>\n              <div class=\"tts-settings\" id=\"tts-common-options\">\n                <div class=\"settings-item\"><label>保存生成音频</label><label class=\"toggle-switch\"><input type=\"checkbox\" id=\"tts-save-audio-switch\"><span class=\"slider\"></span></label></div>\n                <p class=\"tts-usage\">默认仅临时缓存。开启后保存到该条聊天消息，会增加本地存储和备份大小。</p>\n                <details><summary>试听角色语音</summary>\n                  <div class=\"tts-text-row\"><textarea id=\"tts-preview-text\" class=\"tts-wide-input\" rows=\"2\" aria-label=\"角色试听文本\">你好，很高兴见到你。</textarea></div>\n                  <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"tts-preview-generate\">生成试听</button><button type=\"button\" class=\"form-button\" id=\"tts-preview-play\">播放试听</button><button type=\"button\" class=\"form-button\" id=\"tts-preview-stop\">停止</button></div>\n                  <p class=\"tts-usage\">生成试听会产生 API 用量；角色配置保存后用于聊天和通话。</p>\n                </details>\n                <div class=\"tts-actions\"><button type=\"button\" class=\"form-button\" id=\"tts-clear-saved-audio\">清理已保存音频</button></div><p class=\"tts-status\" id=\"tts-role-status\" role=\"status\" aria-live=\"polite\"></p>\n              </div>\n             <div class=\"settings-item\" id=\"ai-voice-lang-group\">\n                <label>语音语言/方言</label>\n                <div class=\"settings-right\">\n                  <select id=\"ai-voice-lang-select\" class=\"settings-select\" style=\"width: 100%; text-align: right;\">\n                    <option value=\"\"> 自动识别 (Auto)</option>\n                    <hr disabled>\n                    <option value=\"zh-CN\">国语/普通话 (Chinese)</option>\n                    <option value=\"zh-HK\">粤语/广东话 (Cantonese)</option>\n                    <option value=\"en-US\">英语 (English)</option>\n                    <option value=\"ja-JP\">日语 (Japanese)</option>\n                    <option value=\"ko-KR\">韩语 (Korean)</option>\n                    <hr disabled>\n                    <option value=\"de-DE\">德语 (German)</option>\n                    <option value=\"fr-FR\">法语 (French)</option>\n                    <option value=\"es-ES\">西班牙语 (Spanish)</option>\n                    <option value=\"it-IT\">意大利语 (Italian)</option>\n                    <option value=\"ru-RU\">俄语 (Russian)</option>\n                    <option value=\"pt-BR\">葡萄牙语 (Portuguese)</option>\n                    <option value=\"nl-NL\">荷兰语 (Dutch)</option>\n                    <option value=\"pl-PL\">波兰语 (Polish)</option>\n                    <option value=\"sv-SE\">瑞典语 (Swedish)</option>\n                    <hr disabled>\n                    <option value=\"tr-TR\">土耳其语 (Turkish)</option>\n                    <option value=\"id-ID\">印尼语 (Indonesian)</option>\n                    <option value=\"ms-MY\">马来语 (Malay)</option>\n                    <option value=\"vi-VN\">越南语 (Vietnamese)</option>\n                    <option value=\"th-TH\">泰语 (Thai)</option>\n                    <option value=\"hi-IN\">印地语 (Hindi)</option>\n                   <option value=\"ar-SA\">阿拉伯语 (Arabic)</option>\n                 </select>\n               </div>\n            </div>\n             <div class=\"settings-item\" id=\"ai-voice-speed-group\">\n               <label>语音速度</label>\n               <div class=\"settings-right\">\n                 <input type=\"number\" id=\"ai-voice-speed-input\" min=\"0.5\" max=\"2.0\" step=\"0.1\" value=\"1.0\" style=\"width: 80px; text-align: right; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; background: var(--secondary-bg); color: var(--text-color);\">\n                 <span style=\"margin-left: 5px; color: var(--text-secondary); font-size: 12px;\">x</span>\n               </div>\n             </div>\n             <div class=\"voice-input-settings\" id=\"voice-input-settings\">\n               <div class=\"settings-item\" id=\"real-voice-enable-group\">\n                 <div style=\"flex: 1; padding-right: 10px;\">\n                   <label style=\"margin-bottom: 2px;\">启用真实语音</label>\n                   <div class=\"settings-desc\">保留原有模拟语音，并允许录制、发送和播放你的原声</div>\n                 </div>\n                 <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"enable-real-voice-switch\"><span class=\"slider\"></span></label>\n               </div>\n               <div id=\"real-voice-config-container\" style=\"display: none;\">\n                 <div class=\"voice-settings-note\">安卓/iOS 建议选“自动”或“后台转文字”；Gemini 音频理解使用当前 Gemini API 配置，Claude/DeepSeek 请走转写接口。</div>\n                 <div class=\"settings-item voice-config-row\">\n                   <label for=\"real-voice-operation-select\">聊天录音方式</label>\n                   <select id=\"real-voice-operation-select\" class=\"settings-select voice-settings-select\">\n                     <option value=\"tap\">点击开始/结束</option>\n                     <option value=\"hold\">按住说话</option>\n                   </select>\n                 </div>\n                 <div class=\"settings-item voice-config-row\">\n                   <label for=\"voice-understanding-mode-select\">角色理解方式</label>\n                   <select id=\"voice-understanding-mode-select\" class=\"settings-select voice-settings-select\">\n                     <option value=\"auto\">自动选择</option>\n                     <option value=\"transcription\">后台转文字</option>\n                     <option value=\"gemini\">Gemini 音频理解</option>\n                     <option value=\"browser\">浏览器识别（旧方式）</option>\n                     <option value=\"none\">仅发送原声</option>\n                   </select>\n                 </div>\n                 <div id=\"voice-transcription-settings\" class=\"voice-nested-settings\">\n                   <div class=\"settings-item voice-field-row\">\n                     <label for=\"voice-transcription-url-input\">转写接口</label>\n                     <input type=\"url\" id=\"voice-transcription-url-input\" class=\"voice-settings-input\" placeholder=\"OpenAI 兼容 /audio/transcriptions\">\n                   </div>\n                   <div class=\"settings-item voice-field-row\">\n                     <label for=\"voice-transcription-model-input\">转写模型</label>\n                     <input type=\"text\" id=\"voice-transcription-model-input\" class=\"voice-settings-input\" placeholder=\"whisper-1\">\n                   </div>\n                   <div class=\"settings-item voice-field-row\">\n                     <label for=\"voice-transcription-key-input\">转写密钥</label>\n                     <input type=\"password\" id=\"voice-transcription-key-input\" class=\"voice-settings-input\" autocomplete=\"off\" placeholder=\"留空时使用主 API Key\">\n                   </div>\n                 </div>\n                 <div class=\"settings-item voice-config-row\">\n                   <label for=\"voice-max-duration-select\">最长录音</label>\n                   <select id=\"voice-max-duration-select\" class=\"settings-select voice-settings-select\">\n                     <option value=\"30\">30 秒</option>\n                     <option value=\"60\">60 秒</option>\n                     <option value=\"120\">120 秒</option>\n                   </select>\n                 </div>\n                 <div class=\"settings-item\">\n                   <div style=\"flex: 1; padding-right: 10px;\">\n                     <label style=\"margin-bottom: 2px;\">发送前确认文字</label>\n                     <div class=\"settings-desc\">识别失败也不会丢失录音，可手动补充或直接发送原声</div>\n                   </div>\n                   <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"voice-confirm-transcript-switch\"><span class=\"slider\"></span></label>\n                 </div>\n                 <div class=\"voice-settings-title voice-call-settings-title\">语音电话输入</div>\n                 <div class=\"settings-item voice-config-row\">\n                   <label for=\"voice-call-input-mode-select\">我的说话方式</label>\n                   <select id=\"voice-call-input-mode-select\" class=\"settings-select voice-settings-select\">\n                     <option value=\"text\">文字输入（原方式）</option>\n                     <option value=\"hold\">按住说话</option>\n                     <option value=\"tap\">点击开始/结束</option>\n                   </select>\n                 </div>\n                 <div class=\"settings-item voice-config-row\">\n                   <label for=\"voice-call-understanding-select\">电话理解方式</label>\n                   <select id=\"voice-call-understanding-select\" class=\"settings-select voice-settings-select\">\n                     <option value=\"same\">跟随聊天设置</option>\n                     <option value=\"auto\">自动选择</option>\n                     <option value=\"transcription\">后台转文字</option>\n                     <option value=\"gemini\">Gemini 音频理解</option>\n                     <option value=\"browser\">浏览器识别（旧方式）</option>\n                     <option value=\"none\">仅记录原声</option>\n                   </select>\n                 </div>\n                 <div class=\"settings-item\">\n                   <div style=\"flex: 1; padding-right: 10px;\">\n                     <label style=\"margin-bottom: 2px;\">识别失败可补文字</label>\n                     <div class=\"settings-desc\">保留电话原有文字输入作为可恢复操作</div>\n                   </div>\n                   <label class=\"toggle-switch\" style=\"margin: 0;\"><input type=\"checkbox\" id=\"voice-call-text-fallback-switch\"><span class=\"slider\"></span></label>\n                 </div>\n               </div>\n             </div>\n <div class=\"settings-item\" id=\"synth-music-group\">\n    <div>\n        <label>启用乐谱合成</label>\n        <div class=\"settings-desc\">允许角色发送乐谱并自动演奏</div>\n    </div>\n    <label class=\"toggle-switch\">\n        <input type=\"checkbox\" id=\"enable-synth-music-switch\">\n        <span class=\"slider\"></span>\n    </label>\n</div>\n<div class=\"settings-item\" id=\"narrator-mode-group\" style=\"display: flex; justify-content: space-between; align-items: center;\">\n    <div style=\"flex: 1; padding-right: 10px;\">\n        <label style=\"margin-bottom: 2px;\">启用旁白模式</label>\n        <div class=\"settings-desc\">AI每轮回复都会附带环境或心理描写 (灰色系统字)</div>\n    </div>\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \n        <input type=\"checkbox\" id=\"narrator-mode-toggle\">\n        <span class=\"slider\"></span>\n    </label>\n</div>\n\n<!-- 双语模式设置 -->\n<div class=\"settings-item\" id=\"bilingual-mode-group\" style=\"display: flex; justify-content: space-between; align-items: center;\">\n    <div style=\"flex: 1; padding-right: 10px;\">\n        <label style=\"margin-bottom: 2px;\">启用语言与翻译</label>\n        <div class=\"settings-desc\">可自动或手动指定角色输出语言、翻译语言和语音朗读内容</div>\n    </div>\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \n        <input type=\"checkbox\" id=\"bilingual-mode-toggle\"> \n        <span class=\"slider\"></span> \n    </label>\n</div>\n\n<div id=\"language-policy-settings\" style=\"display: none;\">\n    <div class=\"settings-item language-policy-row\">\n        <label for=\"language-output-mode-select\">角色输出语言</label>\n        <div class=\"language-policy-control\">\n            <select id=\"language-output-mode-select\" class=\"settings-select\">\n                <option value=\"auto\">自动选择</option>\n                <option value=\"persona\">根据角色设定并保持</option>\n                <option value=\"user\">跟随用户语言</option>\n                <option value=\"fixed\">手动指定</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"settings-item language-policy-row\" id=\"language-output-custom-row\" style=\"display: none;\">\n        <label for=\"language-output-input\">指定输出语言</label>\n        <div class=\"language-policy-control\">\n            <input type=\"text\" id=\"language-output-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"搜索或直接描述语言、方言\">\n            <div id=\"language-output-suggestions\" class=\"language-suggestions\"></div>\n        </div>\n    </div>\n    <div class=\"settings-item language-policy-row\">\n        <label for=\"language-translation-mode-select\">翻译语言</label>\n        <div class=\"language-policy-control\">\n            <select id=\"language-translation-mode-select\" class=\"settings-select\">\n                <option value=\"fixed\">手动指定</option>\n                <option value=\"interface\">跟随应用语言</option>\n                <option value=\"none\">不生成翻译</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"settings-item language-policy-row\" id=\"language-translation-custom-row\">\n        <label for=\"language-translation-input\">指定翻译语言</label>\n        <div class=\"language-policy-control\">\n            <input type=\"text\" id=\"language-translation-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"如 zh-Hans-CN 或自然语言描述\">\n            <div id=\"language-translation-suggestions\" class=\"language-suggestions\"></div>\n        </div>\n    </div>\n    <div class=\"settings-item language-policy-row\">\n        <label for=\"language-tts-read-mode-select\">语音朗读内容</label>\n        <div class=\"language-policy-control\">\n            <select id=\"language-tts-read-mode-select\" class=\"settings-select\">\n                <option value=\"source\">只朗读角色原文</option>\n                <option value=\"translation\">只朗读翻译</option>\n                <option value=\"both\">先原文后翻译</option>\n            </select>\n        </div>\n    </div>\n    <div class=\"settings-item-block\">\n        <button type=\"button\" id=\"language-advanced-toggle\" class=\"language-advanced-toggle\" aria-expanded=\"false\">\n            <span>高级语言设置</span>\n            <span class=\"language-expand-mark\">展开</span>\n        </button>\n    </div>\n    <div id=\"language-advanced-panel\" hidden>\n        <div class=\"settings-item language-advanced-row\">\n            <label for=\"language-switch-policy-select\">语言保持方式</label>\n            <div class=\"language-policy-control\">\n                <select id=\"language-switch-policy-select\" class=\"settings-select\">\n                    <option value=\"dynamic\">按情境自然切换</option>\n                    <option value=\"strict\">严格保持指定语言</option>\n                    <option value=\"explicit\">仅明确要求时切换</option>\n                    <option value=\"natural\">主体固定，允许少量夹杂</option>\n                </select>\n            </div>\n        </div>\n        <div class=\"settings-item language-advanced-row\">\n            <label for=\"language-translation-style-select\">翻译风格</label>\n            <div class=\"language-policy-control\">\n                <select id=\"language-translation-style-select\" class=\"settings-select\">\n                    <option value=\"natural\">自然口语，保留语气</option>\n                    <option value=\"faithful\">忠实准确</option>\n                    <option value=\"concise\">简洁意译</option>\n                    <option value=\"custom\">按自定义规则</option>\n                </select>\n            </div>\n        </div>\n        <div class=\"settings-item language-advanced-row\">\n            <label for=\"language-narration-mode-select\">旁白语言</label>\n            <div class=\"language-policy-control\">\n                <select id=\"language-narration-mode-select\" class=\"settings-select\">\n                    <option value=\"inherit\">沿用现有旁白规则</option>\n                    <option value=\"translation\">使用翻译语言</option>\n                    <option value=\"fixed\">手动指定</option>\n                </select>\n            </div>\n        </div>\n        <div class=\"settings-item language-advanced-row\" id=\"language-narration-custom-row\" style=\"display: none;\">\n            <label for=\"language-narration-input\">指定旁白语言</label>\n            <div class=\"language-policy-control\">\n                <input type=\"text\" id=\"language-narration-input\" class=\"language-policy-input\" autocomplete=\"off\" placeholder=\"搜索或直接描述\">\n                <div id=\"language-narration-suggestions\" class=\"language-suggestions\"></div>\n            </div>\n        </div>\n        <div class=\"settings-item-block\">\n            <label for=\"language-custom-instruction\">自定义语言规则</label>\n            <div class=\"settings-desc\">可描述方言、时代、敬语、夹杂条件、架空语言或任何特殊表达要求。</div>\n            <textarea id=\"language-custom-instruction\" class=\"language-policy-textarea\" placeholder=\"例如：即使用户使用中文也保持韩语；对长辈使用敬语。\"></textarea>\n        </div>\n        <div class=\"settings-item-block\">\n            <label for=\"language-examples-input\">语言示例</label>\n            <div class=\"settings-desc\">可填写角色会怎样说、不会怎样说，以及架空词汇的固定含义。</div>\n            <textarea id=\"language-examples-input\" class=\"language-policy-textarea\" placeholder=\"填写原文、译文或正反示例\"></textarea>\n        </div>\n        <div class=\"settings-item-block\" id=\"language-member-overrides-group\" style=\"display: none;\">\n            <label>群聊成员语言覆盖</label>\n            <div class=\"settings-desc\">留空即沿用群聊设置；可直接输入任意语言、方言或自定义描述。</div>\n            <div id=\"language-member-overrides-list\" class=\"language-member-list\"></div>\n        </div>\n    </div>\n</div>\n\n<!-- 双语模式生效角色 (仅群聊) -->\n<div class=\"settings-item-block\" id=\"bilingual-characters-group\" style=\"display: none;\"> \n    <label>语言与翻译生效角色 (仅群聊)</label>\n    <div class=\"settings-desc\">勾选需要应用语言与翻译规则的角色，未勾选的保持原有单语输出（如果不勾选任何角色，则等同于全员生效）。</div>\n    <div class=\"custom-multiselect\" style=\"margin-top: 5px; position: relative;\" id=\"bilingual-chars-multiselect\">\n        <div class=\"select-box\"> <span class=\"selected-options-text\">-- 点击选择 --</span> <span class=\"arrow-down\">▼</span> </div>\n        <div id=\"bilingual-chars-checkboxes-container\" class=\"checkboxes-container\"> </div>\n    </div>\n</div>\n\n<!-- 双语模式显示位置设置 -->\n<div class=\"settings-item\" id=\"bilingual-display-mode-group\" style=\"display: none;\">\n    <label>翻译显示位置</label>\n    <div class=\"settings-right\">\n        <select id=\"bilingual-display-mode-select\" class=\"settings-select\" style=\"width: 100%; text-align: right;\">\n            <option value=\"outside\">气泡外部</option>\n            <option value=\"inside\">气泡内部</option>\n        </select>\n    </div>\n</div>\n\n<div class=\"settings-item\" id=\"todo-list-setting-group\">\n    <div style=\"flex: 1; padding-right: 10px;\">\n        <label style=\"margin-bottom: 2px;\">启用待办事项同步</label>\n        <div class=\"settings-desc\">开启后，AI将读取【今日】及【未完成】的待办事项。</div>\n    </div>\n    <label class=\"toggle-switch\" style=\"margin: 0;\"> \n        <input type=\"checkbox\" id=\"enable-todo-list-switch\"> \n        <span class=\"slider\"></span> \n    </label>\n</div>\n             <!-- 表情包识图 -->\n             <div class=\"settings-item\" id=\"sticker-vision-group\">\n                 <div>\n                    <label>启用表情包识图</label>\n                    <div class=\"settings-desc\">CHAR可以看到USER表情包的内容</div>\n                 </div>\n                 <label class=\"toggle-switch\"> \n                    <input type=\"checkbox\" id=\"enable-sticker-vision-checkbox\"> \n                    <span class=\"slider\"></span> \n                 </label>\n             </div>\n             \n             <!-- 表情包智能匹配 -->\n             <div class=\"settings-item\" id=\"sticker-smart-match-group\">\n                 <div>\n                    <label>启用表情包智能匹配</label>\n                    <div class=\"settings-desc\">输入文字时自动匹配相关表情包</div>\n                 </div>\n                 <label class=\"toggle-switch\"> \n                    <input type=\"checkbox\" id=\"enable-sticker-smart-match-checkbox\"> \n                    <span class=\"slider\"></span> \n                 </label>\n             </div>\n             \n             <!-- 线下模式 -->\n             <div id=\"offline-mode-group\">\n                 <div class=\"settings-item\">\n                     <div>\n                        <label>线下模式 (描写模式)</label>\n                        <div class=\"settings-desc\">AI将输出包含动作/心理的描写文本</div>\n                     </div>\n                     <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"offline-mode-toggle\"> <span class=\"slider\"></span> </label>\n                 </div>\n                 <div id=\"offline-mode-options\" style=\"display: none; padding: 0 16px 16px 16px;\">\n                     <div style=\"display:flex; align-items:center; gap:10px; margin-bottom:10px;\">\n                        <span style=\"font-size:13px; color:#666;\">字数范围:</span>\n                        <input type=\"number\" id=\"offline-min-length-input\" class=\"settings-num-input\" value=\"100\">\n                        <span>-</span>\n                        <input type=\"number\" id=\"offline-max-length-input\" class=\"settings-num-input\" value=\"300\">\n                     </div>\n                     <label style=\"font-size:13px; color:#666;\">文风预设:</label>\n                     <select id=\"offline-preset-select\" class=\"settings-select\" style=\"width:100%; margin-top:5px;\"></select>\n                     <div style=\"display:flex; align-items:center; justify-content:space-between; margin-top:12px;\">\n                        <div>\n                           <span style=\"font-size:13px; color:#666;\">连续排版模式</span>\n                           <div style=\"font-size:11px; color:#999; margin-top:2px;\">对话与描写不分段，保持自然段落</div>\n                        </div>\n                        <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"offline-continuous-layout-toggle\"> <span class=\"slider\"></span> </label>\n                     </div>\n                 </div>\n             </div>\n\n            <!-- 时间感知 -->\n            <div class=\"settings-item\" id=\"time-perception-group\">\n                <div style=\"min-width: 0; flex: 1; padding-right: 10px;\">\n                    <label>时间感知</label>\n                    <div class=\"settings-desc time-awareness-inline-desc\">让角色感知当前时间与互动间隔</div>\n                </div>\n                <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"time-perception-toggle\"> <span class=\"slider\"></span> </label>\n            </div>\n\n            <div id=\"time-awareness-settings\" class=\"time-awareness-settings\" style=\"display: none;\">\n                <div class=\"settings-item time-awareness-compact-row\">\n                    <label for=\"time-awareness-preset-select\">感知方式</label>\n                    <select id=\"time-awareness-preset-select\" class=\"settings-select time-awareness-select\">\n                        <option value=\"adaptive\">角色自主（推荐）</option>\n                        <option value=\"subtle\">轻微</option>\n                        <option value=\"natural\">自然</option>\n                        <option value=\"strong\">强烈</option>\n                        <option value=\"custom\">自定义</option>\n                    </select>\n                </div>\n                <div id=\"time-awareness-preset-summary\" class=\"time-awareness-summary\"></div>\n\n                <button type=\"button\" id=\"time-awareness-advanced-toggle\" class=\"time-awareness-disclosure\" aria-expanded=\"false\">\n                    <span>高级时间感知设置</span>\n                    <span class=\"time-awareness-disclosure-state\">展开</span>\n                </button>\n\n                <div id=\"time-awareness-advanced-panel\" class=\"time-awareness-advanced-panel\" hidden>\n                    <div class=\"time-awareness-subtitle\">回来判定</div>\n                    <div class=\"settings-item time-awareness-compact-row\">\n                        <label for=\"time-awareness-min-gap-input\">至少离开</label>\n                        <div class=\"time-awareness-number-control\">\n                            <input type=\"number\" id=\"time-awareness-min-gap-input\" class=\"settings-num-input\" min=\"0\" max=\"525600\" step=\"1\" value=\"180\">\n                            <span>分钟</span>\n                        </div>\n                    </div>\n                    <div class=\"settings-item time-awareness-compact-row\">\n                        <label for=\"time-awareness-duration-style-select\">时长表达</label>\n                        <select id=\"time-awareness-duration-style-select\" class=\"settings-select time-awareness-select\">\n                            <option value=\"vague\">模糊自然</option>\n                            <option value=\"approximate\">大致时长</option>\n                            <option value=\"exact\">准确时长</option>\n                        </select>\n                    </div>\n                    <div class=\"settings-item time-awareness-compact-row\">\n                        <label for=\"time-awareness-frequency-select\">回应频率</label>\n                        <select id=\"time-awareness-frequency-select\" class=\"settings-select time-awareness-select\">\n                            <option value=\"autonomous\">角色自主</option>\n                            <option value=\"rare\">偶尔</option>\n                            <option value=\"moderate\">适中</option>\n                            <option value=\"frequent\">经常</option>\n                            <option value=\"always\">每次回来</option>\n                        </select>\n                    </div>\n                    <div id=\"time-awareness-group-options\" hidden>\n                        <div class=\"settings-item time-awareness-compact-row\">\n                            <label for=\"time-awareness-group-gap-basis\">群聊间隔依据</label>\n                            <select id=\"time-awareness-group-gap-basis\" class=\"settings-select time-awareness-select\">\n                                <option value=\"groupSilence\">群聊整体沉默</option>\n                                <option value=\"userAbsence\">用户未在群里发言</option>\n                            </select>\n                        </div>\n                        <div class=\"settings-item time-awareness-compact-row\">\n                            <label for=\"time-awareness-group-max-responders\">最多回应角色</label>\n                            <div class=\"time-awareness-number-control\">\n                                <input type=\"number\" id=\"time-awareness-group-max-responders\" class=\"settings-num-input\" min=\"1\" max=\"20\" step=\"1\" value=\"1\">\n                                <span>人</span>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"time-awareness-subtitle\">提供给角色的信息</div>\n                    <div class=\"time-awareness-toggle-grid\">\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-date\"> 日期与星期</label>\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-time\"> 当前时刻</label>\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-period\"> 早晚时段</label>\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-gap\"> 离开时长</label>\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-last-time\"> 上次互动时间</label>\n                        <label><input type=\"checkbox\" id=\"time-awareness-fact-cross-day\"> 是否跨天</label>\n                    </div>\n\n                    <div class=\"time-awareness-subtitle\">角色反应权限</div>\n                    <div class=\"time-awareness-toggle-list\">\n                        <label><span>允许直接提到离开时间</span><input type=\"checkbox\" id=\"time-awareness-allow-mention\"></label>\n                        <label><span>允许用情绪、想念、担心或不满体现</span><input type=\"checkbox\" id=\"time-awareness-allow-emotion\"></label>\n                        <label><span>允许询问或分享最近的事情</span><input type=\"checkbox\" id=\"time-awareness-allow-updates\"></label>\n                        <label><span>允许在自然时开启新话题</span><input type=\"checkbox\" id=\"time-awareness-allow-new-topic\"></label>\n                        <label><span>允许继续尚未结束的话题</span><input type=\"checkbox\" id=\"time-awareness-allow-continue\"></label>\n                        <label><span>优先回应用户当前消息</span><input type=\"checkbox\" id=\"time-awareness-prioritize-current\"></label>\n                        <label><span>根据角色人设和双方关系调整</span><input type=\"checkbox\" id=\"time-awareness-persona-aware\"></label>\n                        <label><span>离开越久，允许反应越明显</span><input type=\"checkbox\" id=\"time-awareness-scale-gap\"></label>\n                        <label><span>避免机械使用“好久不见”</span><input type=\"checkbox\" id=\"time-awareness-avoid-cliche\"></label>\n                        <label><span>只在回来后的第一轮处理时间差</span><input type=\"checkbox\" id=\"time-awareness-first-reply-only\"></label>\n                    </div>\n\n                    <div class=\"time-awareness-subtitle\">回来反应提示词</div>\n                    <div class=\"settings-item time-awareness-compact-row\">\n                        <label for=\"time-awareness-prompt-mode-select\">使用方式</label>\n                        <select id=\"time-awareness-prompt-mode-select\" class=\"settings-select time-awareness-select\">\n                            <option value=\"builtin\">使用内置规则</option>\n                            <option value=\"append\">内置规则＋我的补充</option>\n                            <option value=\"replace\">完全替换反应规则</option>\n                        </select>\n                    </div>\n                    <div id=\"time-awareness-prompt-editor\" class=\"time-awareness-prompt-editor\" hidden>\n                        <div class=\"time-awareness-variable-hint\">留空时自动回退内置规则。可用变量：{{当前时间}} {{时间段}} {{离开时长}} {{上次互动时间}} {{角色名}} {{用户昵称}} {{双方关系}} {{最近对话状态}}</div>\n                        <textarea id=\"time-awareness-custom-prompt\" class=\"time-awareness-textarea\" rows=\"7\" placeholder=\"写下角色在用户回来时应如何反应……\"></textarea>\n                        <div class=\"time-awareness-actions\">\n                            <button type=\"button\" id=\"time-awareness-reset-prompt-btn\">恢复档位默认</button>\n                            <button type=\"button\" id=\"time-awareness-copy-prompt-btn\">复制</button>\n                        </div>\n                    </div>\n\n                    <div class=\"time-awareness-subtitle\">模拟预览</div>\n                    <div class=\"time-awareness-preview-controls\">\n                        <select id=\"time-awareness-preview-gap\" class=\"settings-select\">\n                            <option value=\"10\">离开 10 分钟</option>\n                            <option value=\"180\">离开 3 小时</option>\n                            <option value=\"2880\">离开 2 天</option>\n                            <option value=\"43200\">离开 30 天</option>\n                        </select>\n                        <button type=\"button\" id=\"time-awareness-preview-btn\">生成预览</button>\n                    </div>\n                    <pre id=\"time-awareness-preview-output\" class=\"time-awareness-preview-output\" hidden></pre>\n\n                    <div class=\"time-awareness-subtitle\">暂停与后台</div>\n                    <div class=\"time-awareness-toggle-list\">\n                        <label><span>世界时间暂停时不累计离开时长</span><input type=\"checkbox\" id=\"time-awareness-pause-gap\"></label>\n                        <label><span>世界时间暂停时暂停本聊天后台活动</span><input type=\"checkbox\" id=\"time-awareness-pause-background\"></label>\n                        <label><span>立即暂停本聊天后台活动</span><input type=\"checkbox\" id=\"time-awareness-background-paused\"></label>\n                        <label><span>后台主动行动也使用自定义回来规则</span><input type=\"checkbox\" id=\"time-awareness-prompt-in-background\"></label>\n                    </div>\n\n                    <div class=\"time-awareness-actions time-awareness-default-actions\">\n                        <button type=\"button\" id=\"time-awareness-save-default-btn\">保存为全局默认</button>\n                        <button type=\"button\" id=\"time-awareness-load-default-btn\">载入全局默认</button>\n                        <button type=\"button\" id=\"time-awareness-export-btn\">导出配置</button>\n                        <button type=\"button\" id=\"time-awareness-import-btn\">导入配置</button>\n                        <input type=\"file\" id=\"time-awareness-import-file\" accept=\".json\" hidden>\n                        <button type=\"button\" id=\"time-awareness-apply-all-btn\">应用到全部聊天</button>\n                    </div>\n                </div>\n            </div>\n\n            <!-- 一起听时长感知 -->\n            <div class=\"settings-item\" id=\"music-time-awareness-group\" style=\"display: none;\">\n                <div style=\"flex: 1; padding-right: 10px;\">\n                    <label style=\"margin-bottom: 2px;\">一起听时长感知</label>\n                    <div class=\"settings-desc\">开启后角色可感知累计一起听歌的时长</div>\n                </div>\n                <label class=\"toggle-switch\" style=\"margin: 0;\">\n                    <input type=\"checkbox\" id=\"music-time-awareness-toggle\">\n                    <span class=\"slider\"></span>\n                </label>\n            </div>\n            <div class=\"settings-item-block\" id=\"time-zone-group\" style=\"display: none;\">\n                <label for=\"time-zone-select\">我的时区</label>\n                <div style=\"margin-top: 10px; width: 100%;\">\n                    <input type=\"search\" id=\"time-zone-search-input\" placeholder=\"搜索城市 / 时区...\" class=\"settings-textarea\" style=\"height: 36px; padding: 8px; margin-bottom: 8px;\">\n                    <select id=\"time-zone-select\" class=\"settings-select\" style=\"width: 100%; padding: 10px; background-color: #f5f5f7;\"></select>\n                </div>\n                <div id=\"character-time-zone-group\" class=\"role-time-zone-control\">\n                    <label for=\"character-time-zone-select\">角色所在地 / 时区</label>\n                    <select id=\"character-time-zone-select\" class=\"settings-select\"><option value=\"\">跟随我的时区</option></select>\n                    <div class=\"settings-desc time-awareness-inline-desc\">选择一次即可自动换算双方时间，包括跨日和夏令时。</div>\n                    <div id=\"role-time-preview\" class=\"role-time-preview\">\n                        <span class=\"role-time-preview-label\">我的时间</span><span id=\"role-time-preview-user\">—</span>\n                        <span class=\"role-time-preview-label\">角色时间</span><span id=\"role-time-preview-character\">—</span>\n                        <span class=\"role-time-preview-label\">当前时差</span><span id=\"role-time-preview-difference\">—</span>\n                    </div>\n                </div>\n                <div id=\"group-time-zone-hint\" class=\"settings-desc time-awareness-inline-desc\" hidden>各成员沿用自己的角色时区，可在群成员设置中修改。</div>\n            </div>\n\n            <!-- 自定义时间 -->\n            <div class=\"settings-item\" id=\"custom-time-group\">\n                <label>自定义时间</label>\n                <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"custom-time-toggle\"> <span class=\"slider\"></span> </label>\n            </div>\n            <div class=\"settings-item-block\" id=\"custom-time-settings-group\" style=\"display: none;\">\n                <label>时间设置</label>\n                <div style=\"margin-top: 10px; width: 100%;\">\n                    <div style=\"display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 10px;\">\n                        <div>\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">年份</label>\n                            <input type=\"number\" id=\"custom-year-input\" class=\"settings-num-input\" placeholder=\"2024\" min=\"1900\" max=\"2100\" style=\"width: 100%;\">\n                        </div>\n                        <div>\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">月份</label>\n                            <input type=\"number\" id=\"custom-month-input\" class=\"settings-num-input\" placeholder=\"1-12\" min=\"1\" max=\"12\" style=\"width: 100%;\">\n                        </div>\n                    </div>\n                    <div style=\"display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; margin-bottom: 10px;\">\n                        <div>\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">日期</label>\n                            <input type=\"number\" id=\"custom-day-input\" class=\"settings-num-input\" placeholder=\"1-31\" min=\"1\" max=\"31\" style=\"width: 100%;\">\n                        </div>\n                        <div>\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">小时</label>\n                            <input type=\"number\" id=\"custom-hour-input\" class=\"settings-num-input\" placeholder=\"0-23\" min=\"0\" max=\"23\" style=\"width: 100%;\">\n                        </div>\n                        <div>\n                            <label style=\"font-size: 12px; color: #666; display: block; margin-bottom: 5px;\">分钟</label>\n                            <input type=\"number\" id=\"custom-minute-input\" class=\"settings-num-input\" placeholder=\"0-59\" min=\"0\" max=\"59\" style=\"width: 100%;\">\n                        </div>\n                    </div>\n                    <div style=\"font-size: 12px; color: #999; margin-top: 5px;\">\n                        当前设置：<span id=\"custom-time-preview\" style=\"color: #007AFF; font-weight: 500;\">未设置</span>\n                    </div>\n                    <div class=\"time-awareness-clock-actions\">\n                        <button type=\"button\" id=\"custom-time-pause-btn\">暂停世界时间</button>\n                        <span id=\"custom-time-pause-status\">运行中</span>\n                    </div>\n                    <div class=\"time-awareness-clock-actions\">\n                        <label for=\"custom-time-rate\">流逝倍率</label>\n                        <input type=\"number\" id=\"custom-time-rate\" class=\"settings-num-input\" min=\"0\" step=\"any\" value=\"1\">\n                        <button type=\"button\" id=\"custom-time-rate-apply\">应用倍率</button>\n                    </div>\n                </div>\n            </div>\n             \n            <div id=\"memory-time-settings-host\"></div>\n\n             <!-- NAI设置 (单聊/群聊复用ID，JS控制) -->\n             <div class=\"settings-item-block\" id=\"nai-character-settings-group\" style=\"display: none;\">\n                <label>NAI 出图设置 (角色专属)</label>\n                <div style=\"margin-top: 10px;\">\n                    <button id=\"character-nai-prompts-btn\" class=\"settings-full-btn\">配置专属提示词</button>\n                </div>\n             </div>\n             <div class=\"settings-item-block\" id=\"group-nai-settings-group\" style=\"display: none;\">\n                <label>NAI 出图设置 (群聊专属)</label>\n                <div style=\"margin-top: 10px;\">\n                    <button id=\"group-character-nai-prompts-btn\" class=\"settings-full-btn\">配置专属提示词</button>\n                </div>\n             </div>\n        </div>\n\n        <!-- 第五组：外观与视觉 -->\n        <div class=\"settings-section\">\n            <div class=\"settings-item\">\n                 <label>聊天背景</label>\n                 <!-- 增加 full-width 类以保持右对齐，内部使用 avatar-btn-group 保持间距一致 -->\n                 <div class=\"settings-right full-width\">\n                     <div class=\"avatar-btn-group\" style=\"justify-content: flex-end; width: 100%;\">\n                         <!-- 升级为实体小按钮 -->\n                         <button class=\"settings-mini-btn\" onclick=\"document.getElementById('bg-input').click()\">上传</button>\n                         <button class=\"settings-mini-btn\" id=\"remove-bg-btn\">移除</button>\n                         \n                         <!-- 保持原有的隐藏 input 和预览图逻辑 -->\n                         <input type=\"file\" id=\"bg-input\" accept=\"image/*\" hidden>\n                         <img id=\"bg-preview\" class=\"settings-bg-preview\">\n                     </div>\n                 </div>\n            </div>\n            \n            <div class=\"settings-item-block\">\n                <label>气泡主题</label>\n                 <div style=\"display:flex; justify-content:space-between; margin-bottom:10px; align-items:center;\">\n                    <select id=\"theme-preset-select\" class=\"settings-select\" style=\"flex:1; margin-right:10px;\"></select>\n                    <div style=\"display:flex; gap:6px;\">\n                        <button id=\"save-theme-preset-btn\" class=\"settings-mini-btn\" title=\"保存预设\" style=\"padding: 4px 8px; font-size: 12px;\">保存</button>\n                        <button id=\"delete-theme-preset-btn\" class=\"settings-mini-btn\" title=\"删除预设\" style=\"padding: 4px 8px; font-size: 12px; color:#ff3b30;\">删除</button>\n                    </div>\n                 </div>\n                 <!-- 补全所有主题选项 -->\n                 <div class=\"theme-selector\" id=\"theme-selector-container\" style=\"max-height: 120px; overflow-y: auto; display: flex; flex-wrap: wrap; gap: 12px; padding: 5px 0;\">\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"default\" id=\"theme-default\"> 默认</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_blue\"> 粉蓝</label> \n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_white\"> 蓝白</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"purple_yellow\"> 紫黄</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"black_white\"> 黑白</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"yellow_white\"> 黄白</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"red_black\"> 红黑</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_yellow\"> 蓝黄</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_yellow\"> 粉黄</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_purple\"> 粉紫</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"gray_white\"> 灰白</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"blue_green\"> 蓝绿</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_white\"> 粉白</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_black\"> 粉黑</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"pink_green\"> 粉绿</label>\n                      <label><input type=\"radio\" name=\"theme-select\" value=\"green_black\"> 绿黑</label>\n                      \n                      <!-- 动态渲染的自定义预设将插入在这里 -->\n                      \n                      <button id=\"reset-theme-btn\" class=\"settings-text-btn\" style=\"margin-left: auto;\">重置默认</button>\n                 </div>\n                 \n                 <!-- 新增：自定义气泡颜色功能区 -->\n                 <div style=\"margin-top: 10px; padding-top: 10px; border-top: 1px dashed rgba(0,0,0,0.1);\">\n                     <div style=\"display: flex; gap: 10px; align-items: center; margin-bottom: 8px;\">\n                         <label style=\"font-size: 13px; color: var(--text-secondary);\">我的气泡</label>\n                         <input type=\"color\" id=\"custom-user-bubble-color\" value=\"#fff0f6\" style=\"width: 30px; height: 30px; padding: 0; border: none; cursor: pointer;\">\n                         <label style=\"font-size: 13px; color: var(--text-secondary); margin-left: 10px;\">对方气泡</label>\n                         <input type=\"color\" id=\"custom-ai-bubble-color\" value=\"#eff7ff\" style=\"width: 30px; height: 30px; padding: 0; border: none; cursor: pointer;\">\n                     </div>\n                     <div style=\"display: flex; flex-direction: column; gap: 8px;\">\n                         <input type=\"text\" id=\"custom-theme-name\" placeholder=\"自定义颜色名称...\" style=\"width: 100%; box-sizing: border-box; padding: 8px; border: 1px solid var(--border-color); border-radius: 6px; font-size: 14px;\">\n                         <div style=\"display: flex; gap: 8px; justify-content: flex-end;\">\n                             <button id=\"add-custom-theme-btn\" class=\"settings-mini-btn\" style=\"background-color: var(--accent-color); color: white;\">保存预设</button>\n                             <button id=\"manage-custom-themes-btn\" class=\"settings-mini-btn\">管理</button>\n                         </div>\n                     </div>\n                 </div>\n            </div>\n\n            <div class=\"settings-item\">\n                 <label>字体大小 <span id=\"chat-font-size-value\" style=\"color:#888; font-size:12px;\">13px</span></label>\n                 <div class=\"settings-right\" style=\"width: 50%;\">\n                    <input type=\"range\" id=\"chat-font-size-slider\" min=\"12\" max=\"20\" step=\"1\" style=\"width:100%;\">\n                 </div>\n            </div>\n            \n            <div class=\"settings-item-block\">\n                 <label style=\"display: flex; justify-content: space-between; align-items: center;\">\n                     <div style=\"display: flex; align-items: center; gap: 5px;\">\n                         自定义 CSS\n                         <button type=\"button\" onclick=\"openFullscreenEditor('custom-css-input', '当前聊天自定义 CSS')\" title=\"放大编辑\" style=\"background: none; border: none; cursor: pointer; color: #888; padding: 4px; display: flex; align-items: center; justify-content: center;\">\n                             <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7\"/></svg>\n                         </button>\n                     </div>\n                     <button id=\"reset-custom-css-btn\" style=\"font-size:12px;\">重置</button>\n                 </label>\n                 <textarea id=\"custom-css-input\" rows=\"3\" class=\"settings-textarea\" placeholder=\"/* 针对当前聊天的CSS */\"></textarea>\n                 <p style=\"font-size: 12px; color: var(--text-secondary); line-height: 1.6;\">支持 <code>{{char_name}}</code> 本名、<code>{{char_remark}}</code> 备注、<code>{{user_name}}</code> 我的全局昵称、<code>{{user_nickname}}</code> 当前聊天昵称，以及 <code>{{char_avatar}}</code>、<code>{{user_avatar}}</code> 头像。示例：<code>.message-bubble.ai::after { content: \"{{char_name}}\"; }</code></p>\n            </div>\n\n            <div class=\"settings-item-block\">\n                <label>效果预览</label>\n                <div id=\"settings-preview-area\" style=\"margin-top:10px;\"></div>\n            </div>\n            \n            <div class=\"settings-item-block\" id=\"lyrics-position-group\" style=\"display: none;\">\n                 <label>歌词栏设置</label>\n                 <div style=\"display:flex; gap:10px; margin-top:10px;\">\n                     <select id=\"lyrics-vertical-pos\" class=\"settings-select\"><option value=\"top\">顶部</option><option value=\"bottom\">底部</option></select>\n                     <select id=\"lyrics-horizontal-pos\" class=\"settings-select\"><option value=\"center\">居中</option><option value=\"left\">居左</option><option value=\"right\">居右</option></select>\n                     <input type=\"number\" id=\"lyrics-offset-input\" class=\"settings-num-input\" value=\"10\" placeholder=\"偏移\">\n                 </div>\n            </div>\n        </div>\n\n        <!-- 第六组：数据与操作 (底部) -->\n        <div class=\"settings-section\">\n             <div class=\"settings-item clickable\" id=\"search-history-btn\">\n                 <label>查找聊天记录</label>\n                 <div class=\"settings-right\">›</div>\n             </div>\n             \n             <div class=\"settings-item clickable\" id=\"export-single-chat-btn\">\n                 <label>导出聊天记录</label>\n                 <div class=\"settings-right\">›</div>\n             </div>\n             \n             <div class=\"settings-item clickable\" id=\"import-single-chat-btn\">\n                 <label>导入聊天记录</label>\n                 <div class=\"settings-right\">\n                     ›\n                     <input type=\"file\" id=\"import-single-chat-input\" accept=\"application/json\" hidden>\n                 </div>\n             </div>\n\n             <div class=\"settings-item clickable\" id=\"export-character-full-btn\">\n                 <label>导出角色</label>\n                 <div class=\"settings-right\">›</div>\n             </div>\n\n             <div class=\"settings-item clickable\" id=\"clear-chat-btn\">\n                 <label style=\"color: #ff3b30;\">清空聊天记录</label>\n                 <div class=\"settings-right\">›</div>\n             </div>\n             \n             <div class=\"settings-item clickable\" id=\"block-chat-btn\">\n                 <label style=\"color: #ff3b30;\">拉黑对方 / 移出群聊</label>\n                 <div class=\"settings-right\">›</div>\n             </div>\n        </div>\n        \n        <div style=\"height: 40px;\"></div> <!-- 底部垫高 -->\n      </div>\n    </div>\n    <div id=\"rendering-rules-screen\" class=\"screen\">\n      <div class=\"header\"> \n        <span class=\"back-btn\" onclick=\"showScreen('home-screen')\">‹</span> \n        <span data-lang-key=\"homeAppRenderer\">渲染规则</span> \n        <div class=\"header-actions\">\n            <div class=\"rules-more-wrapper\">\n                <span class=\"action-btn\" id=\"rules-more-btn\" title=\"更多操作\" aria-haspopup=\"true\" aria-expanded=\"false\">\n                    <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                        <circle cx=\"12\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\n                        <circle cx=\"19\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\n                        <circle cx=\"5\" cy=\"12\" r=\"1.5\" fill=\"currentColor\"></circle>\n                    </svg>\n                </span>\n                <div class=\"rules-dropdown-menu\" id=\"rules-more-menu\" style=\"display: none;\">\n                    <button type=\"button\" class=\"rules-dropdown-item\" id=\"import-rules-btn\">\n                        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"7 10 12 15 17 10\"></polyline><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line></svg>\n                        <span>导入规则</span>\n                    </button>\n                    <button type=\"button\" class=\"rules-dropdown-item\" id=\"manage-rules-btn\">\n                        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                            <path d=\"M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11\"></path>\n                            <polyline points=\"9 11 12 14 22 4\"></polyline>\n                        </svg>\n                        <span id=\"manage-rules-btn-text\">批量管理</span>\n                    </button>\n                </div>\n            </div>\n            <span class=\"action-btn\" id=\"rules-exit-manage-btn\" title=\"完成管理\" style=\"display: none;\">\n                <svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                    <polyline points=\"20 6 9 17 4 12\"></polyline>\n                </svg>\n            </span>\n            <span class=\"action-btn\" id=\"add-new-rule-btn\" title=\"创建新规则\">+</span> \n        </div>\n      </div>\n      <div id=\"rules-tabs\"> </div>\n      <div id=\"rules-content-container\" class=\"list-container\"> </div>\n      \n      <div id=\"rules-action-bar\" style=\"display: none; position: absolute; bottom: 0; left: 0; width: 100%; padding: 15px 20px; background: rgba(255,255,255,0.95); backdrop-filter: blur(10px); border-top: 1px solid #eee; box-sizing: border-box; justify-content: space-between; align-items: center; z-index: 10;\">\n          <label style=\"display:flex; align-items:center; gap:5px; font-size:16px;\">\n              <input type=\"checkbox\" id=\"select-all-rules-checkbox\"> 全选\n          </label>\n          <div style=\"display:flex; gap:10px;\">\n              <button id=\"export-selected-rules-btn\" class=\"settings-mini-btn\" style=\"background-color: #007aff; color: white; border: none;\">导出 (0)</button>\n              <button id=\"delete-selected-rules-btn\" class=\"settings-mini-btn\" style=\"color: #ff3b30;\">删除 (0)</button>\n          </div>\n      </div>\n    </div>\n    <input type=\"file\" id=\"import-rules-input\" accept=\".json\" style=\"display: none;\">\n    <div id=\"rule-editor-modal\" class=\"modal\">\n      <div class=\"modal-content\" style=\"height: 85%;\">\n        <div class=\"modal-header\"> <span id=\"rule-editor-title\">创建新规则</span> </div>\n        <div class=\"modal-body\" style=\"display: flex; flex-direction: column; gap: 15px;\">\n          <div class=\"form-group\" style=\"flex-shrink: 0;\"> <label for=\"rule-name-input\">规则名称</label> <input type=\"text\" id=\"rule-name-input\" placeholder=\"例如：美团外卖卡片\"> </div>\n          <div class=\"form-group\" style=\"flex-shrink: 0;\"> <label for=\"rule-chat-id-select\">绑定范围</label> <select id=\"rule-chat-id-select\">\n              <option value=\"global\">公用 (所有角色)</option>\n            </select> </div>\n          <div class=\"form-group\" style=\"flex-grow: 1; display: flex; flex-direction: column;\"> <label for=\"rule-regex-input\">正则表达式 (使用g作为标志)</label> <textarea id=\"rule-regex-input\" rows=\"3\" style=\"font-family: monospace; resize: vertical;\" placeholder=\"例如：MTR\\[(.*?)\\]\\[(.*?)\\|(.*?)\\]\"></textarea>\n          </div>\n          <div class=\"form-group\" style=\"flex-grow: 2; display: flex; flex-direction: column;\"> <label for=\"rule-template-input\">替换内容 / HTML 模板 (用 $1, $2 引用)</label> <textarea id=\"rule-template-input\" rows=\"6\" style=\"font-family: monospace; resize: vertical;\"\n              placeholder=\"例如：<div class=`waimai-card`>...<span>$2</span>...</div>\"></textarea> </div>\n          <div class=\"form-group\" style=\"display: flex; justify-content: space-between; align-items: center; flex-shrink: 0;\"> <label for=\"rule-enabled-switch\" style=\"margin-bottom: 0;\">启用规则</label> <label class=\"toggle-switch\"> <input type=\"checkbox\" id=\"rule-enabled-switch\" checked>\n              <span class=\"slider\"></span> </label> </div>\n<div class=\"form-group\" style=\"display: flex; justify-content: space-between; align-items: center; flex-shrink: 0;\">\n    <label for=\"rule-do-not-send-switch\" style=\"margin-bottom: 0;\">\n        发送给 AI 前删除匹配内容\n        <p style=\"font-size: 12px; font-weight: normal; color: #999; margin-top: 5px;\">\n            开启后，仅删除发送给 AI 的匹配片段；显示仍按模板处理。\n        </p>\n    </label>\n    <label class=\"toggle-switch\">\n        <input type=\"checkbox\" id=\"rule-do-not-send-switch\">\n        <span class=\"slider\"></span>\n    </label>\n</div>\n        </div>\n        <div class=\"modal-footer\"> <button class=\"cancel\" id=\"cancel-rule-editor-btn\" data-lang-key=\"cancel\">取消</button> <button class=\"save\" id=\"save-rule-btn\"data-lang-key=\"save\">保存规则</button> </div>\n      </div>\n    </div>\n";
